<?php

declare(strict_types=1);

namespace Waffle\Tests;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
use Waffle\Enum\WebhookErrorReason;
use Waffle\Exception\WaffleException;
use Waffle\Exception\WebhookVerificationException;
use Waffle\Webhook;

/**
 * Fixed vectors computed independently with
 *   printf '%s.' "$T"; cat body | openssl dgst -sha256 -hmac "$SECRET"
 * (legacy: openssl dgst -sha256 -hmac "$SECRET" body). Not generated by the code under test.
 */
final class WebhookTest extends TestCase
{
    private const SECRET = 'whsec_test_secret';
    private const OTHER_SECRET = 'whsec_other_secret';
    private const T = 1767323045;

    private const BODY1 = '{"event":"charge.paid","event_id":"d1b0c3a2-0000-4000-8000-000000000001","created_at":"2026-01-02T03:04:05Z","charge_id":"ch_123","status":"paid","amount":100000,"currency":"IDR","mode":"live"}';
    private const BODY2 = '{"event":"payout.failed","event_id":"d1b0c3a2-0000-4000-8000-000000000002","created_at":"2026-01-02T03:04:05Z","payout_id":"po_9","status":"failed","amount":40000,"currency":"IDR","mode":"sandbox","reason":"Rekening tidak valid — gagal ✓ 日本"}';

    private const B1_V2 = '2018c5555c6d3aba3f16464677fe2628fa66e5cf786fcbd31d5078c9d6a864dc';
    private const B1_LEGACY = '830202cbcc20bf66c1b459df8ee96d5ef164e4f43390807f446187b5c1511e14';
    private const B2_V2 = '87bfb14fd6261671132d2b078f40fc9ea4c67336aa73988b6a1b10019145b168';
    private const B1_V2_OTHER = '7c8fcaa519041e148e2234293fc512a63f9b3b3bbb6dc2105c18663851a49e22';
    private const B1_OLD300 = '060fac12a9ec992be04a2be745791a02e478477bc2e7cec6ca04b91aba002b1f'; // t=T-300
    private const B1_OLD301 = '9319089c36da45fc5ac85360df30e02a66d6f6af3b2723b4c7a4a69aac2fed40'; // t=T-301
    private const B1_FUT300 = '012b80fde0d53dec2fda184843acba55558a03eb2968fad97bd6f891b2ed3ed1'; // t=T+300
    private const B1_FUT301 = '43548ff997ef4d6f1982da040a5a03923cd7ef02a60b69135d00f3095c12256c'; // t=T+301
    private const NOT_JSON_SIG = '11cc8c1fd3d46b04aba00e94652bfafdf22a53504b570f4e0e47462e3b05654a'; // body "not json"
    private const ARRAY_SIG = 'ce111e366acba8c7e5d2cbf2544eed1850defc0e565adbcc826f94d784506e74'; // body "[1]"

    private const V2 = 'X-Waffle-Signature-V2';

    private static function clock(): callable
    {
        return static fn (): int => self::T;
    }

    /** @param array<string,string> $headers */
    private function assertRejected(
        WebhookErrorReason $want,
        string $body,
        array $headers,
        string $secret = self::SECRET,
        int $tolerance = 300,
        bool $allowLegacy = true,
    ): void {
        try {
            Webhook::verify($body, $headers, $secret, $tolerance, self::clock(), $allowLegacy);
            self::fail('expected WebhookVerificationException');
        } catch (WebhookVerificationException $e) {
            self::assertSame($want, $e->reason);
            self::assertInstanceOf(WaffleException::class, $e);
            self::assertStringNotContainsString($secret, $e->getMessage());
        }
    }

    public function testValidV2ReturnsTypedEnvelope(): void
    {
        $ev = Webhook::verify(
            self::BODY1,
            [self::V2 => 't=' . self::T . ',v1=' . self::B1_V2, 'X-Waffle-Delivery' => 'd1b0c3a2-0000-4000-8000-000000000001'],
            self::SECRET,
            now: self::clock(),
        );

        self::assertSame('charge.paid', $ev->event);
        self::assertSame('d1b0c3a2-0000-4000-8000-000000000001', $ev->eventId);
        self::assertSame('2026-01-02T03:04:05Z', $ev->createdAt);
        self::assertSame('ch_123', $ev->chargeId);
        self::assertNull($ev->payoutId);
        self::assertSame('paid', $ev->status);
        self::assertSame(100000, $ev->amount);
        self::assertSame('IDR', $ev->currency);
        self::assertSame('live', $ev->mode);
        self::assertSame('d1b0c3a2-0000-4000-8000-000000000001', $ev->deliveryId);
        self::assertSame('ch_123', $ev->raw['charge_id']);
    }

    public function testUnicodeBody(): void
    {
        $ev = Webhook::verify(self::BODY2, [self::V2 => 't=' . self::T . ',v1=' . self::B2_V2], self::SECRET, now: self::clock());

        self::assertSame('po_9', $ev->payoutId);
        self::assertSame('Rekening tidak valid — gagal ✓ 日本', $ev->raw['reason']);
        self::assertSame('sandbox', $ev->mode);
    }

    public function testTamperedBody(): void
    {
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1 . ' ', [self::V2 => 't=' . self::T . ',v1=' . self::B1_V2]);
    }

    public function testWrongSecret(): void
    {
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1, [self::V2 => 't=' . self::T . ',v1=' . self::B1_V2], self::OTHER_SECRET);
    }

    public function testSignedWithOtherSecret(): void
    {
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1, [self::V2 => 't=' . self::T . ',v1=' . self::B1_V2_OTHER]);
    }

    public function testAlteredTimestampBreaksSignature(): void
    {
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1, [self::V2 => 't=' . (self::T + 1) . ',v1=' . self::B1_V2]);
    }

    public function testStaleAndFutureTimestamps(): void
    {
        $this->assertRejected(WebhookErrorReason::TimestampOutOfTolerance, self::BODY1, [self::V2 => 't=' . (self::T - 301) . ',v1=' . self::B1_OLD301]);
        $this->assertRejected(WebhookErrorReason::TimestampOutOfTolerance, self::BODY1, [self::V2 => 't=' . (self::T + 301) . ',v1=' . self::B1_FUT301]);
        $this->assertRejected(WebhookErrorReason::TimestampOutOfTolerance, self::BODY1, [self::V2 => 't=' . (self::T - 301) . ',v1=' . self::B1_OLD301], tolerance: 60);
    }

    public function testToleranceBoundaryIsInclusive(): void
    {
        $a = Webhook::verify(self::BODY1, [self::V2 => 't=' . (self::T - 300) . ',v1=' . self::B1_OLD300], self::SECRET, now: self::clock());
        $b = Webhook::verify(self::BODY1, [self::V2 => 't=' . (self::T + 300) . ',v1=' . self::B1_FUT300], self::SECRET, now: self::clock());
        self::assertSame('charge.paid', $a->event);
        self::assertSame('charge.paid', $b->event);
    }

    /** @return iterable<string,array{string}> */
    public static function malformedV2(): iterable
    {
        yield 'no v1' => ['t=' . self::T];
        yield 'no t' => ['v1=' . self::B1_V2];
        yield 'garbage' => ['garbage'];
        yield 'empty' => [''];
        yield 't not numeric' => ['t=abc,v1=' . self::B1_V2];
        yield 'negative t' => ['t=-5,v1=' . self::B1_V2];
        yield 'duplicate t' => ['t=' . self::T . ',t=' . self::T . ',v1=' . self::B1_V2];
        yield 'v1 not hex' => ['t=' . self::T . ',v1=zzzz'];
        yield 'v1 short' => ['t=' . self::T . ',v1=abcd'];
    }

    #[DataProvider('malformedV2')]
    public function testMalformedV2Header(string $header): void
    {
        $this->assertRejected(WebhookErrorReason::MalformedHeader, self::BODY1, [self::V2 => $header]);
    }

    /** @return iterable<string,array{array<string,string>}> */
    public static function acceptedHeaders(): iterable
    {
        $good = 't=' . self::T . ',v1=' . self::B1_V2;
        yield 'lowercase name' => [['x-waffle-signature-v2' => $good]];
        yield 'uppercase name' => [['X-WAFFLE-SIGNATURE-V2' => $good]];
        yield 'extra whitespace' => [[self::V2 => '  t=' . self::T . ' ,  v1=' . self::B1_V2 . '  ']];
        yield 'unknown fields' => [[self::V2 => 't=' . self::T . ',v0=deadbeef,v1=' . self::B1_V2 . ',v9=x']];
        yield 'multiple v1, second matches' => [[self::V2 => 't=' . self::T . ',v1=' . self::B1_V2_OTHER . ',v1=' . self::B1_V2]];
        yield 'multiple v1, first matches' => [[self::V2 => 't=' . self::T . ',v1=' . self::B1_V2 . ',v1=' . self::B1_V2_OTHER]];
        yield 'uppercase hex' => [[self::V2 => 't=' . self::T . ',v1=' . strtoupper(self::B1_V2)]];
    }

    /** @param array<string,string> $headers */
    #[DataProvider('acceptedHeaders')]
    public function testHeaderLeniency(array $headers): void
    {
        $ev = Webhook::verify(self::BODY1, $headers, self::SECRET, now: self::clock());
        self::assertSame('charge.paid', $ev->event);
    }

    public function testMissingSignature(): void
    {
        $this->assertRejected(WebhookErrorReason::MissingSignature, self::BODY1, []);
    }

    public function testLegacyAllowedByDefaultHasNoTimestampCheck(): void
    {
        $h = ['x-waffle-signature' => 'sha256=' . self::B1_LEGACY, 'X-Waffle-Delivery' => 'abc'];
        $ev = Webhook::verify(self::BODY1, $h, self::SECRET, now: static fn (): int => 1);

        self::assertSame('charge.paid', $ev->event);
        self::assertSame('abc', $ev->deliveryId);
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1 . ' ', $h);
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1, $h, self::OTHER_SECRET);
    }

    public function testLegacyDisallowed(): void
    {
        $this->assertRejected(WebhookErrorReason::MissingSignature, self::BODY1, ['X-Waffle-Signature' => 'sha256=' . self::B1_LEGACY], allowLegacy: false);
    }

    public function testLegacyMalformed(): void
    {
        $this->assertRejected(WebhookErrorReason::MalformedHeader, self::BODY1, ['X-Waffle-Signature' => self::B1_LEGACY]);
    }

    public function testInvalidV2NeverFallsBackToLegacy(): void
    {
        $this->assertRejected(WebhookErrorReason::SignatureMismatch, self::BODY1, [
            self::V2 => 't=' . self::T . ',v1=' . self::B1_V2_OTHER,
            'X-Waffle-Signature' => 'sha256=' . self::B1_LEGACY,
        ]);
    }

    public function testInvalidJson(): void
    {
        $this->assertRejected(WebhookErrorReason::InvalidJson, 'not json', [self::V2 => 't=' . self::T . ',v1=' . self::NOT_JSON_SIG]);
        $this->assertRejected(WebhookErrorReason::InvalidJson, '[1]', [self::V2 => 't=' . self::T . ',v1=' . self::ARRAY_SIG]);
    }

    public function testEmptySecretIsRejected(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        Webhook::verify(self::BODY1, [], '');
    }
}
